import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, uniform } from 'three/tsl';
import * as GSAP from 'gsap';

export default async function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const disposables = [];
  const timelines = [];

  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // === BACKDROP PLANE with gradient ===
  {
    const geom = new THREE.PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();

    const y = uv().y;
    const c0 = uniform(new THREE.Color('#0b0b10'));
    const c1 = uniform(new THREE.Color('#101017'));
    const c2 = uniform(new THREE.Color('#16161d'));

    const t1 = y.div(0.65);
    const seg1 = mix(c0, c1, t1);

    const t2 = y.sub(0.65).div(0.35);
    const seg2 = mix(c1, c2, t2);

    const selector = smoothstep(0.62, 0.68, y);
    mat.colorNode = mix(seg1, seg2, selector);

    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.z = -3;
    group.add(mesh);

    disposables.push(() => {
      geom.dispose();
      mat.dispose();
    });
  }

  // === FOG ===
  group.fog = new THREE.Fog(new THREE.Color(colors.background), 5, 11);

  // === LOAD GEARS ===
  let primaryGearMesh = null;
  try {
    const gltf = await ctx.glbLoader.loadGLB(config.meshUrl);
    if (gltf.scene && gltf.scene.children.length > 0) {
      primaryGearMesh = gltf.scene.children[0];
    }
  } catch (e) {
    console.error('GLB load failed:', e);
  }

  if (!primaryGearMesh) {
    group.userData.cleanup = () => {
      disposables.forEach(fn => { try { fn(); } catch (e) {} });
      timelines.forEach(tl => { if (tl && tl.kill) tl.kill(); });
    };
    return group;
  }

  // === GEAR MATERIAL (machined steel) ===
  const gearMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3
  });

  // === PRIMARY GEAR ===
  primaryGearMesh.scale.set(1.6, 1.6, 1.6);
  primaryGearMesh.position.set(0, 0, 0);
  primaryGearMesh.traverse(child => {
    if (child.isMesh) {
      child.material = gearMat;
    }
  });
  group.add(primaryGearMesh);

  // === SECONDARY GEAR ===
  const secondaryGear = primaryGearMesh.clone();
  secondaryGear.scale.set(0.9, 0.9, 0.9);
  secondaryGear.position.set(1.15, 0.35, -0.1);
  group.add(secondaryGear);

  // === JEWEL PIVOT SPHERE ===
  {
    const geom = new THREE.SphereGeometry(0.12, 32, 32);
    const mat = new MeshPhysicalNodeMaterial({
      color: new THREE.Color(colors.accent),
      transmission: 0.6,
      ior: 1.76,
      emissive: new THREE.Color(colors.accent),
      emissiveIntensity: 1.8
    });
    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.set(0, 0, 0);
    group.add(mesh);

    disposables.push(() => {
      geom.dispose();
      mat.dispose();
    });
  }

  // === ARBOR SHAFTS ===
  {
    const geom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
    const mat = new MeshStandardNodeMaterial({
      color: new THREE.Color(colors.ink)
    });

    const primaryShaft = new THREE.Mesh(geom, mat);
    primaryShaft.position.set(0, 0, 0);
    group.add(primaryShaft);

    const secondaryShaft = new THREE.Mesh(geom, mat);
    secondaryShaft.position.set(1.15, 0.35, -0.1);
    group.add(secondaryShaft);

    disposables.push(() => {
      geom.dispose();
      mat.dispose();
    });
  }

  // === CONTACT SHADOW ===
  {
    const geom = new THREE.PlaneGeometry(2.6, 1.2);
    const mat = new MeshBasicNodeMaterial();
    mat.color = new THREE.Color(colors.background);
    mat.transparent = true;
    mat.opacity = 0.5;

    const mesh = new THREE.Mesh(geom, mat);
    mesh.position.set(0, -1.2, 0.1);
    mesh.rotation.x = -Math.PI / 2;
    group.add(mesh);

    disposables.push(() => {
      geom.dispose();
      mat.dispose();
    });
  }

  // === TEXT LABELS ===
  {
    const headline = ctx.fontAtlas.createText('The going train', {
      fontSize: 68,
      color: colors.paper,
      align: 'center'
    });
    headline.position.set(0, -1.7, 0);
    group.add(headline);
  }

  {
    const caption = ctx.fontAtlas.createText('34 COMPONENTS / HAND-FINISHED', {
      fontSize: 18,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 1.44
    });
    caption.position.set(0, -2.1, 0);
    group.add(caption);
  }

  // === GEAR ROTATION ===
  {
    const rot1 = GSAP.to(primaryGearMesh.rotation, {
      z: '+=6.283185307',
      duration: (Math.PI * 2) / 0.08,
      ease: 'none',
      repeat: -1
    });
    timelines.push(rot1);

    const rot2 = GSAP.to(secondaryGear.rotation, {
      z: '-=6.283185307',
      duration: (Math.PI * 2) / 0.142,
      ease: 'none',
      repeat: -1
    });
    timelines.push(rot2);
  }

  // === ORBIT PRIMITIVE ===
  {
    const result = ctx.primitives['orbit'](group, {
      speed: 0.08,
      radius: 0.2
    });
    if (result) {
      if (result.cleanup) disposables.push(() => result.cleanup());
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  // === CLEANUP ===
  group.userData.cleanup = () => {
    disposables.forEach(fn => { try { fn(); } catch (e) {} });
    timelines.forEach(tl => { if (tl && tl.kill) tl.kill(); });
  };

  return group;
}
